(ns metabase.metabot.tools.autogen-dashboard
  "The `create_autogenerated_dashboard` tool."
  (:require
   [clojure.string :as str]
   [metabase.api.common :as api]
   [metabase.metabot.agent.streaming :as streaming]
   [metabase.metabot.db :as metabot.db]
   [metabase.metabot.scope :as scope]
   [metabase.metabot.tools.core :as tools]
   [metabase.metabot.tools.run-query :as run-query]
   [metabase.util.log :as log]))

(set! *warn-on-reflection* true)

;;; Source Resolution

(tools/defrecoverable invalid-source!
  "The call set no source, or more than one."
  {:payload [:map {:closed true}]}
  [_]
  {:message  "Set exactly one of `table_id`, `model_id`, `metric_id`, `query_id` or `report_id` in `source`."
   :recovery []})

(tools/defrecoverable unavailable-source!
  "The user can read the source, but it is in the trash, or it is a table that is gone from its database."
  {:payload [:map {:closed true}
             [:kind [:enum :table :model :metric :question]]
             [:id   :int]]}
  [{:keys [kind id]}]
  {:message  (str (str/capitalize (name kind)) " " id
                  (if (= :table kind)
                    " is no longer in its database."
                    " is in the trash."))
   :recovery [{:uses #{"search"}
               :text "Call `search` to find another source and use an id from the results."}]})

(defn- readable-source
  "The `kind` entity with `id` and its X-ray path, if the current user can read it and it is still in use."
  [kind id]
  (let [entity (tools/with-entity {:kind kind :id id}
                 (api/read-check (if (= :table kind)
                                   (metabot.db/table id)
                                   (metabot.db/card-of-type id kind))))]
    (when (or (:archived entity) (false? (:active entity)))
      (unavailable-source! {:kind kind :id id}))
    {:entity entity
     :path   (str "/auto/dashboard/" (name kind) "/" id)}))

(defn- resolve-source
  "The X-ray path for `source` under `:path`, and the table or card that it reads under `:entity`.
  A `query_id` names one of `queries`, the conversation's queries, and has no `:entity`."
  [{:keys [table_id model_id metric_id query_id report_id] :as source} queries]
  (when-not (= 1 (count (remove nil? (vals source))))
    (invalid-source! {}))
  (cond
    table_id  (readable-source :table table_id)
    model_id  (readable-source :model model_id)
    metric_id (readable-source :metric metric_id)
    report_id (readable-source :question report_id)

    query_id
    (if (get queries query_id)
      {:path (str "/auto/dashboard/adhoc/" query_id)}
      (run-query/unknown-query-id! {:query-id query_id :known-ids (vec (keys queries))}))))

(def ^:private autogen-dashboard-schema
  [:map {:closed true}
   [:source [:map {:closed true}
             [:table_id {:optional true} [:maybe :int]]
             [:model_id {:optional true} [:maybe :int]]
             [:metric_id {:optional true} [:maybe :int]]
             [:query_id {:optional true} [:maybe :string]]
             [:report_id {:optional true} [:maybe :int]]]]])

(defrecord CreateAutogeneratedDashboardTool []
  tools/Tool
  (declaration [_]
    {:name        "create_autogenerated_dashboard"
     :description (str "Create an automatically generated dashboard using Metabase's X-ray feature.\n\n"
                       "X-ray builds complete dashboards with multiple visualizations that showcase different "
                       "aspects of your data - distributions, breakdowns by categories, trends over time, and "
                       "relationships between fields.\n\n"
                       "Specify one source type:\n"
                       "- table_id: Create dashboard for a table\n"
                       "- model_id: Create dashboard for a model\n"
                       "- metric_id: Create dashboard for a metric\n"
                       "- query_id: Create dashboard for query results from this conversation\n"
                       "- report_id: Create dashboard for an existing report/question")
     :scope       scope/agent-dashboard-create
     :args        autogen-dashboard-schema})

  (handle [_ {:keys [source]} {:keys [memory-atom]}]
    (log/info "Creating autogenerated dashboard" {:source source})
    ;; The X-ray itself runs when the frontend opens `path`
    (let [{:keys [entity path]} (resolve-source source (get-in (some-> memory-atom deref) [:state :queries] {}))]
      (log/info "Autogenerated dashboard created" {:path path})
      {:output     (str "The dashboard has been created and the user has been navigated to view it. Briefly "
                        "acknowledge this (1 sentence) and stop. Do not describe the dashboard contents.")
       :data-parts [(streaming/dashboard-entity-part {:title (or (:display_name entity) (:name entity) "Dashboard")
                                                      :url   path})]})))

(def create-autogenerated-dashboard-tool
  "The `create_autogenerated_dashboard` tool."
  (->CreateAutogeneratedDashboardTool))
